import { useState } from 'react';
import { SignIn } from '@/components/Auth/SignIn';
import { SignUp } from '@/components/Auth/SignUp';
import { TaskForm } from '@/components/TaskManager/TaskForm';
import { TaskList } from '@/components/TaskManager/TaskList';
import { useAuth } from '@/components/Auth/AuthContext';
import { Task, TaskUpdates } from '@/components/TaskManager/types';
import { v4 as uuidv4 } from 'uuid';

export default function Home() {
  const { user } = useAuth();
  const [showSignUp, setShowSignUp] = useState(false);
  const [tasks, setTasks] = useState<Task[]>([]);

  const toggleForm = () => setShowSignUp((prev) => !prev);

  // Add new task
  const handleAddTask = (task: TaskUpdates) => {
    const newTask: Task = {
      id: uuidv4(),
      completed: false,
      createdAt: new Date().toISOString(),
      ...task,
    };
    setTasks((prev) => [...prev, newTask]);
  };

  // Edit existing task
  const handleEditTask = (id: string, updates: Partial<Task>) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, ...updates } : t))
    );
  };

  const handleCancelEdit = () => console.log('Cancel edit');

  const handleToggleComplete = (id: string) =>
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );

  const handleDeleteTask = (id: string) =>
    setTasks((prev) => prev.filter((t) => t.id !== id));

  const handleSetEditingTask = (task: Task) =>
    console.log('Set editing', task);

  // --- Show login/signup if not authenticated ---
  if (!user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 dark:bg-gray-900 p-6">
        <h1 className="text-3xl font-bold mb-6 text-gray-800 dark:text-gray-200">
          Task Manager
        </h1>

        {showSignUp ? (
          <SignUp onSignUpSuccess={() => console.log('Signed up!')} />
        ) : (
          <SignIn onLoginSuccess={() => console.log('Logged in!')} />
        )}

        <button
          className="mt-4 text-blue-500 hover:underline"
          onClick={toggleForm}
        >
          {showSignUp
            ? 'Already have an account? Sign In'
            : "Don't have an account? Sign Up"}
        </button>
      </div>
    );
  }

  // --- Show task manager if authenticated ---
  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 p-6">
      <h1 className="text-3xl font-bold mb-6 text-gray-800 dark:text-gray-200">
        Welcome, {user.name}!
      </h1>

      <TaskForm
        darkMode={false}
        onAddTask={handleAddTask}
        onEditTask={handleEditTask}
        onCancelEdit={handleCancelEdit}
      />

      <TaskList
        tasks={tasks}
        darkMode={false}
        toggleComplete={handleToggleComplete}
        deleteTask={handleDeleteTask}
        editTask={handleEditTask}
        setEditingTask={handleSetEditingTask}
      />
    </div>
  );
}
